<?php
require 'config/auth.php';
require 'config/db.php';
require 'config/financial_actions.php';
if(!has_permission('control.view')&&!has_permission('control.manage'))require_permission('control.view');

$year=(int)($_GET['year']??$_POST['fiscal_year']??fiscal_year_for_date());
$unitId=is_admin()?(int)($_GET['unit_id']??0):current_unit_id();
$selectedAccount=(int)($_GET['account_id']??0);
$error='';
$labels=['increase'=>'เงินเพิ่ม','transfer_out'=>'โอนออก','return_army'=>'ส่งคืน ทบ.','carry'=>'กันไว้เบิก','request'=>'ขอใช้','obligation'=>'ผูกพัน','payment'=>'ตัดจ่าย','remittance'=>'นำส่ง','base'=>'งบตั้งต้น','transfer_in'=>'เงินโอนเข้า','use'=>'ใช้จ่าย','advance'=>'เงินยืม','po_reserve'=>'กันเงิน PO'];

if($_SERVER['REQUEST_METHOD']==='POST'){
    require_permission('control.manage');
    $accountId=(int)($_POST['control_account_id']??0);
    $selectedAccount=$accountId;
    $stmt=$conn->prepare('SELECT id,unit_id,fiscal_year,gfmis_code,activity_code FROM control_accounts WHERE id=?');
    $stmt->bind_param('i',$accountId);$stmt->execute();$account=$stmt->get_result()->fetch_assoc();
    if(!$account||!can_access_unit((int)$account['unit_id'])||(int)$account['fiscal_year']!==$year){$error='กรุณาเลือกบัญชีคุมงบประมาณ ในปีงบประมาณที่ถูกต้อง';}
    else{
        $unitId=is_admin()?(int)$account['unit_id']:current_unit_id();
        try { begin_financial_transaction($conn);
            ledger_add($conn,$accountId,$_POST['trans_date']??'',$_POST['entry_type']??'',(float)($_POST['amount']??0),(int)$account['unit_id'],(string)$account['gfmis_code'],(string)$account['activity_code'],(int)($_POST['disbursement_no']??0),'',trim($_POST['remark']??''),current_user_id());
            $conn->commit();
            header('Location: transactions.php?year='.$year.'&unit_id='.$unitId.'&account_id='.$accountId.'&saved=1');exit;
        }catch(Throwable $e){$conn->rollback();$error=operation_error($e);}
    }
}
$units=$conn->query('SELECT id,unit_code,unit_name FROM units ORDER BY unit_code')->fetch_all(MYSQLI_ASSOC);
$accountSql='SELECT ca.id,ca.budget_code,ca.item_name,ca.gfmis_code,ca.activity_code,ca.received_amount,ca.unit_id,u.unit_code,COALESCE(SUM(CASE WHEN e.entry_type="increase" THEN e.amount WHEN e.entry_type IN ("transfer_out","return_army","payment","remittance") THEN -e.amount ELSE 0 END),0) movement FROM control_accounts ca JOIN units u ON u.id=ca.unit_id LEFT JOIN active_control_entries e ON e.control_account_id=ca.id WHERE ca.cancelled_at IS NULL AND ca.fiscal_year=?'.($unitId>0?' AND ca.unit_id=?':'').' GROUP BY ca.id ORDER BY u.unit_code,ca.budget_code';
$stmt=$conn->prepare($accountSql);$unitId>0?$stmt->bind_param('ii',$year,$unitId):$stmt->bind_param('i',$year);$stmt->execute();$accounts=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$accountIds=array_map('intval',array_column($accounts,'id'));if($selectedAccount&&!in_array($selectedAccount,$accountIds,true))$selectedAccount=0;

$legacySql="SELECT t.trans_date AS event_date,t.id AS event_id,t.trans_type AS event_type,t.amount,t.remark AS note,u.unit_code,COALESCE(ca.budget_code,'') AS budget_code,ca.id AS account_id,'transaction' AS origin,t.ref_table AS source_table,t.ref_id AS source_id FROM budget_transactions t JOIN units u ON u.id=t.unit_id LEFT JOIN budget_transfers bt ON t.ref_table='budget_transfers' AND bt.id=t.ref_id LEFT JOIN budget_disbursements bd ON t.ref_table='budget_disbursements' AND bd.id=t.ref_id LEFT JOIN control_accounts ca ON ca.source_transfer_id=COALESCE(bt.id,bd.source_transfer_id) WHERE t.cancelled_at IS NULL AND t.ledger_entry_id IS NULL AND t.fiscal_year=?".($unitId>0?' AND t.unit_id=?':'');
$entrySql="SELECT e.entry_date AS event_date,e.id AS event_id,e.entry_type AS event_type,e.amount,e.note,u.unit_code,ca.budget_code,ca.id AS account_id,'ledger' AS origin,e.source_table,e.source_id FROM active_control_entries e JOIN control_accounts ca ON ca.id=e.control_account_id JOIN units u ON u.id=ca.unit_id WHERE e.amount<>0 AND ca.cancelled_at IS NULL AND ca.fiscal_year=?".($unitId>0?' AND ca.unit_id=?':'');
$sql='SELECT * FROM ('.$legacySql.' UNION ALL '.$entrySql.') events ORDER BY event_date DESC,event_id DESC';
$stmt=$conn->prepare($sql);if($unitId>0)$stmt->bind_param('iiii',$year,$unitId,$year,$unitId);else $stmt->bind_param('ii',$year,$year);$stmt->execute();$events=$stmt->get_result();
?>
<!doctype html><html lang="th"><head><meta name="viewport" content="width=device-width, initial-scale=1"><meta charset="utf-8"><title>รายการการเงินตามบัญชีคุม</title><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"></head><body><?php require 'template/nav.php';?><main class="container">
<section class="panel"><h1 class="page-title">รายการการเงินตามบัญชีคุม</h1><p class="page-subtitle">เลือกรหัสงบประมาณ ก่อนบันทึกการตัดจ่าย ระบบจะนำยอดไปแสดงในบัญชีคุมและรายงานทันที</p><form method="get" class="toolbar"><label>ปีงบประมาณ</label><input type="number" name="year" value="<?=$year?>" min="2500" max="3000" style="width:150px"><?php if(is_admin()):?><label>หน่วย</label><select name="unit_id" style="width:300px"><option value="0">ทุกหน่วย</option><?php foreach($units as $unit):?><option value="<?=(int)$unit['id']?>" <?=$unitId===(int)$unit['id']?'selected':''?>><?=htmlspecialchars($unit['unit_code'].' '.$unit['unit_name'])?></option><?php endforeach;?></select><?php endif;?><button class="btn btn-primary">แสดงรายการ</button></form></section>
<section class="panel"><h2>บัญชีที่เลือกตัดจ่ายได้</h2><div class="table-wrap"><table><tr><th>หน่วย</th><th>รหัสงบประมาณ</th><th>รายการ</th><th>รหัส GFMIS</th><th class="text-right">รับ</th><th class="text-right">คงเหลือ</th><th>จัดการ</th></tr><?php foreach($accounts as $a):?><tr><td><?=htmlspecialchars($a['unit_code'])?></td><td><a href="control_account_detail.php?id=<?=(int)$a['id']?>"><?=htmlspecialchars($a['budget_code'])?></a></td><td><?=htmlspecialchars($a['item_name'])?></td><td><?=htmlspecialchars($a['gfmis_code'])?></td><td class="text-right"><?=number_format((float)$a['received_amount'],2)?></td><td class="text-right"><?=number_format((float)$a['received_amount']+(float)$a['movement'],2)?></td><td><a href="?year=<?=$year?>&unit_id=<?=$unitId?>&account_id=<?=(int)$a['id']?>#entry">เลือกบัญชีนี้</a></td></tr><?php endforeach;?><?php if(!$accounts):?><tr><td colspan="7">ยังไม่มีบัญชีคุมในปีนี้</td></tr><?php endif;?></table></div></section>
<?php if(has_permission('control.manage')):?><section class="panel" id="entry"><h2>เพิ่มรายการในบัญชีคุม</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert alert-success">บันทึกและปรับยอดบัญชีคุมแล้ว</div><?php endif;?><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="fiscal_year" value="<?=$year?>"><div class="form-grid form-grid-2"><label>บัญชีคุมงบประมาณ *</label><select name="control_account_id" required><option value="">-- เลือกบัญชีที่จะตัดจ่าย --</option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=$selectedAccount===(int)$a['id']?'selected':''?>><?=htmlspecialchars($a['budget_code'].' | '.$a['unit_code'].' | '.$a['item_name'].' | คงเหลือ '.number_format((float)$a['received_amount']+(float)$a['movement'],2))?></option><?php endforeach;?></select><label>วันที่</label><input type="date" name="trans_date" value="<?=date('Y-m-d')?>" required><label>เบิกครั้งที่/ลำดับเอกสาร</label><input type="number" min="1" name="disbursement_no" required><label>ประเภทรายการ</label><select name="entry_type"><option value="payment">ตัดจ่าย</option><option value="transfer_out">โอนออก</option><option value="return_army">ส่งคืน ทบ.</option><option value="remittance">นำส่ง</option><option value="increase">เพิ่มงบ</option><option value="carry">กันไว้เบิก</option><option value="request">ขอใช้</option><option value="obligation">ผูกพัน</option></select><label>จำนวนเงิน</label><input type="number" step="0.01" min="0.01" name="amount" required><label>หมายเหตุ</label><input type="text" name="remark"></div><div class="toolbar" style="margin-top:16px"><button class="btn btn-success" <?=$accounts?'':'disabled'?>>บันทึกลงบัญชีที่เลือก</button></div></form></section><?php endif;?>
<section class="panel"><h2>ประวัติรายการล่าสุด</h2><div class="table-wrap"><table><tr><th>วันที่</th><th>หน่วย</th><th>รหัสงบประมาณ</th><th>ประเภท</th><th class="text-right">จำนวนเงิน</th><th>หมายเหตุ</th><th>จัดการ</th></tr><?php while($e=$events->fetch_assoc()):?><tr><td><?=htmlspecialchars($e['event_date'])?></td><td><?=htmlspecialchars($e['unit_code'])?></td><td><?php if($e['account_id']):?><a href="control_account_detail.php?id=<?=(int)$e['account_id']?>"><?=htmlspecialchars($e['budget_code'])?></a><?php else:?>ไม่ผูกบัญชี<?php endif;?></td><td><?=htmlspecialchars($labels[$e['event_type']]??$e['event_type'])?></td><td class="text-right"><?=number_format((float)$e['amount'],2)?></td><td><?=htmlspecialchars((string)$e['note'])?></td><td><?php if(has_permission('control.manage')): $url=financial_source_url($e['source_table'],(int)$e['source_id'],$year)??('financial_entry.php?origin='.($e['origin']==='ledger'?'ledger':'transaction').'&id='.(int)$e['event_id']);?><a href="<?=htmlspecialchars($url)?>">แก้ไข / ลบ</a><?php endif;?></td></tr><?php endwhile;?></table></div></section>
</main></body></html>
